--
-- Table structure for table `pos_item`
--

DROP TABLE IF EXISTS `pos_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pos_item` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `pos_id` bigint unsigned NOT NULL,
  `med_id` bigint unsigned DEFAULT NULL,
  `med_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `expire_date` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `quantity` int NOT NULL DEFAULT '0',
  `act_price` double(8,2) DEFAULT '0.00',
  `margin` double(8,2) DEFAULT '0.00',
  `sell_price` double(8,2) NOT NULL DEFAULT '0.00',
  `unit` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '0',
  `total_price` double(8,2) DEFAULT NULL,
  `discount` double(8,2) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `pos_item_pos_id_foreign` (`pos_id`),
  KEY `pos_item_med_id_foreign` (`med_id`),
  CONSTRAINT `pos_item_med_id_foreign` FOREIGN KEY (`med_id`) REFERENCES `pharmacy` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pos_item_pos_id_foreign` FOREIGN KEY (`pos_id`) REFERENCES `pos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=24050 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

